# content_livd.py — 간질환 사망(LIVD, K70-K76) 원고의 Methods·Results 문장(수치는 numbers_livd에서만).
#  규칙: 구조화 초록 ≤250, 번호 인용 [n], 미국식 철자.
#  LLM 사용은 Methods에 기록, Statements and Declarations. 인용 = [@key] 또는 [@web:...]. 단독 저자 → 1인칭 금지. 결과 절에 해석 금지. 제목 쌍점 금지, 시리즈 제목 틀 반복 금지.
#  공변량은 "간질환 사망 역학 문헌에 근거해 고른 세트" — "pre-specified/before any model was fitted" 문구 금지. 결과 열람 뒤 추가한 것(농가 비율 사후 검정)은 Methods에 그 사실을 적는다.
from numbers_livd import load, ROB, RS
import os, pandas as pd
N = load()
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f} to {t[2]:.3f}"
def ci(v): r = N["main"][v]; return tci((r["IRR"], r["lo"], r["hi"]))
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["s41"][("H1_nco_" + o, v)]
S41 = lambda a, v: N["s41"][(a, v)]
S44 = lambda a, v: N["s44"][(a, v)]
S45 = lambda a, v: N["s45"][(a, v)]
SC = lambda s, v: N["sens_main"][s][v]
EN = {"강원도": "Gangwon", "충청남도": "South Chungcheong", "충청북도": "North Chungcheong", "경기도": "Gyeonggi", "서울시": "Seoul", "경상북도": "North Gyeongsang",
      "경상남도": "South Gyeongsang", "전라남도": "South Jeolla", "전라북도": "North Jeolla", "광주시": "Gwangju", "부산시": "Busan", "인천시": "Incheon", "울산시": "Ulsan",
      "대전시": "Daejeon", "세종시": "Sejong", "대구시": "Daegu", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
ALC, BAR, HCV, ABD, DMS, SMK, WALK, MPA, FAC, IMS, BLS = ("high_risk_drinking_rate", "alcohol_venues_per10k", "hcv_notification_rate_log", "screening_abdominal_obesity_share",
    "screening_diabetes_suspected_share", "current_smoking_rate", "walking_practice_rate", "moderate_pa_rate", "public_sports_facilities_per_100k", "im_specialists_per_100k", "basic_livelihood_rate")
TITLE = "Why are liver disease deaths higher in some Korean districts than in others?"
KEYWORDS = "Alcohol Drinking; Hepatitis C; Liver Diseases; Mortality; Poverty; Smoking; Spatial Analysis"
assert ":" not in TITLE and "2011" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and len(TITLE.split()) <= 20
_kw = [k.strip() for k in KEYWORDS.split(";")]; assert 4 <= len(_kw) <= 7 and _kw == sorted(_kw, key=str.lower)
_LK = pd.read_csv(os.path.join(RS, "S1_likelihood.csv")); _LK = _LK[_LK.set == "REF_forced_only"].set_index("family").WAIC
_FAM = pd.read_csv(os.path.join(RS, "S3_main_fit.csv")).family.iloc[0]
assert _FAM == "nbinomial" and _LK["nbinomial"] < _LK["poisson"] and abs(_LK["nbinomial"] - N["waic_forced"]) < 0.15
NHYP = N["n_hyp"]; EXP_CHANCE = 0.05 * NHYP; assert NHYP == 11
SUP = {"methods": "Supplementary Material, Supplementary Methods", "covariates": "Supplementary Material, Table S1", "datacheck": "Supplementary Material, Table S2", "specs": "Supplementary Material, Table S3",
       "regions": "Supplementary Material, Table S4", "prespec": "Supplementary Material, Table S5", "reverse": "Supplementary Material, Table S6", "persistence": "Supplementary Material, Figure S1", "types": "Supplementary Material, Figure S2"}
def sup(k): return SUP[k]
WN = ("W1_2011-15", "W2_2016-19", "W3_2020-24")
_W = pd.read_csv(os.path.join(RS, "S4_window_IRR.csv")).set_index(["cov", "window"])
def wt(v, w): r = _W.loc[(v, w)]; return (r.IRR, r.lo, r.hi, bool(r.cred))
RET = N["ret14"]; NALT = RET[BLS][1]
BEST = min(KH, key=lambda a: N["s43_waic"][a]); assert BEST == "KH_typeII" and dW(BEST) < 0
BW = lambda v, part: N["bw"][f"{v}__{part}"]
_hot = N["type_class"]["hotspot"]; _nt = N["n_type"]; _cold = N["type_class"]["coldspot"]
_NC = lambda v: tci((N["negctl"][v]["IRR"], N["negctl"][v]["lo"], N["negctl"][v]["hi"]))
ASR = N["asr"]; WSD = N["within_sd"]
AI_METHODS = "The author used Claude (Anthropic) and ChatGPT (OpenAI) only for translation and English-language editing of the manuscript."

METHODS = [
("Design, outcome and population",
 f"This ecological study used annual deaths from liver diseases (International Classification of Diseases, 10th revision, K70-K76: alcohol-related liver disease, toxic liver disease, hepatic failure, chronic hepatitis, fibrosis and cirrhosis, other inflammatory and other diseases of the liver) in 2011-2024 by district of residence from the national cause-of-death statistics, which cover all registered deaths [@web:kostat2026cause]. Liver cancer (C22) and viral hepatitis (B15-B19) are coded elsewhere and were not included. Data were extracted in October-November 2026. Districts were harmonized to {N['n_districts']} units with 2024 boundaries ({N['n_rows']:,} district-years), with resident populations by 5-year age group as denominators [@web:mois2026population] ({sup('methods')})."),
("Age standardization",
 "Expected deaths were obtained by indirect standardization: national age-specific liver disease death rates in seventeen 5-year age groups and an open-ended group aged 85 years or older were applied to each district's age structure each year, and expected deaths were rescaled to the national total of observed deaths each year [@inskip1983methods]. Observed over expected deaths gives the standardized mortality ratio (SMR). National trends were directly standardized to the 2015 population. The principal standardization was by age, with the sex ratio included as a forced control; sex- and age-specific national rates were used in a sensitivity analysis."),
("District characteristics",
 f"Eleven district characteristics were selected on the basis of the epidemiological literature on liver disease mortality, which identifies alcohol, hepatitis C and hepatitis B viruses and metabolic dysfunction as the main causes [@devarbhavi2023global; @gbd2020global; @rinella2023multisociety] and smoking, physical activity and deprivation as modifiers [@dam2013smoking; @simon2020physical; @askgaard2024population], with access to care as a candidate contextual indicator. Alcohol was represented by the age-standardized share of adults with high-risk drinking [@kang2015korea] and by the density of entertainment and singing bars per 10,000 residents from business licensing records, a marker of alcohol availability [@campbell2009effectiveness]. Hepatitis C was represented by the notification rate of hepatitis C per 100,000 person-years over 2017-2024 (log scale), a time-invariant district characteristic, because hepatitis C became nationally notifiable in mid-2017 [@web:kdca2026notifiable]; no district indicator of chronic hepatitis B was available. Metabolic dysfunction was represented by the shares of national health screening participants with abdominal obesity and with suspected diabetes on measured fasting glucose among those not under treatment [@kang2022current]. Behaviors were the age-standardized shares of current smokers, of adults walking regularly and of adults doing moderate-or-vigorous physical activity, and public sports facilities per 100,000 residents. Care capacity was internal medicine specialists per 100,000 residents and deprivation was the share of basic livelihood security recipients. The share of urban residents, physicians per 1,000 residents, the sex ratio, fiscal autonomy and the share aged 80 years or older were forced into every model to absorb urbanization and residual age structure. Definitions, sources, years observed and filled cells are listed in {sup('covariates')}; data checks are summarized in {sup('datacheck')}. Covariates were standardized to mean 0 and standard deviation (SD) 1. Fires per 10,000 residents and the share of adults eating breakfast served as negative-control exposures without a direct pathway to liver deaths, although both may share upstream determinants such as drinking or deprivation [@lipsitch2010negative]."),
("Statistical analysis",
 f"The likelihood was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model. Models had an offset of log expected deaths, a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@besag1991bayesian; @riebler2016intuitive; @simpson2017penalising], and random-walk and independent year effects, fitted by integrated nested Laplace approximation [@rue2009approximate] in R [@web:rcore2026]. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. Intervals were not adjusted for multiplicity; with {NHYP} characteristics, about {EXP_CHANCE:.2f} intervals would be expected to exclude 1 by chance if none were associated. Spatial clustering was described by Moran's I [@moran1950notes], residual hot and cold spots by the posterior probability (above 0.95 or below 0.05) that the residual spatial RR exceeded 1, and persistence by Kendall's W and emerging hot spot analysis, which combines yearly Getis-Ord Gi* statistics [@getis1992analysis] with Mann-Kendall trend tests. A characteristic was called subset-stable when its interval excluded 1 in at least 75% of 200 random covariate subsets with at least 95% sign agreement. Robustness was examined with Knorr-Held type I-IV space-time interactions [@knorrheld2000bayesian], alternative neighborhood graphs, alternative likelihoods and year effects, Spatial+ [@dupont2022spatial], 1- and 2-year lags, calendar windows, leave-one-province and leave-one-year-out refits, 20 perturbations of filled values, between- and within-district decomposition (district mean and two-way-centered deviation, not directly comparable with the principal estimate) [@bell2015explaining], sex- and age-standardized expected deaths, E-values [@vanderweele2017sensitivity] and two exploratory comparison outcomes without a direct liver pathway, deaths from chronic lower respiratory diseases and Alzheimer disease ({sup('specs')}). Model checks were the residual Moran's I, posterior predictive coverage, the probability integral transform and a refit with 2024 deaths withheld. Region-specific slopes were estimated for subset-stable characteristics ({sup('regions')}). Six sensitivity analyses added suspected liver disease at screening (an intermediate), the out-of-district outpatient share, monthly drinking or district-type fixed effects, replaced abdominal obesity by self-reported obesity, or entered the physical activity indicators alone ({sup('prespec')}). After the results were seen, the positive association of moderate-or-vigorous physical activity was examined post hoc by adding the share of farm-household residents, in a single-covariate model and without the other physical activity indicators ({sup('reverse')})."),
("Ethics and reporting",
 "The study used only published aggregate statistics. The Institutional Review Board of Hongik University approved the study on November 4, 2025 (7002340-202511-HR-012) and its continuing review on November 3, 2026 (7002340-202611-HR-040), and waived informed consent. Reporting follows the Strengthening the Reporting of Observational Studies in Epidemiology (STROBE) statement [@vonelm2007strengthening] (Supplementary Material, STROBE checklist)."),
]

CRED6 = [HCV, BLS, SMK, DMS, MPA, FAC]   # 주모형 credible 6개(수급률 33칸 정정 재실행)
RESULTS = [
("Deaths and trends",
 f"Over 2011-2024, {N['cases_total']:,} liver disease deaths occurred in {N['py']/1e6:.0f} million person-years (Table 1). The directly age-standardized rate fell from {N['asr_2011']:.1f} per 100,000 in 2011 to {ASR[2019]:.1f} in 2019 and was {min(ASR[t] for t in range(2020, 2025)):.1f}-{max(ASR[t] for t in range(2020, 2025)):.1f} in 2020-2024 ({N['asr_2024']:.1f} in 2024), while the crude rate rose from {N['crude_2011']:.1f} in 2011 to {N['crude_2024']:.1f} in 2024 (Figure 1B). The 10th-90th percentile range of district SMRs over the whole period was {T1['2011-2024']['sir_p10']:.2f}-{T1['2011-2024']['sir_p90']:.2f}."),
("Geography",
 f"Moran's I was {N['moran_pooled']:.2f} for pooled log SMRs and {N['moran_year_min']:.2f}-{N['moran_year_max']:.2f} annually, Kendall's W for the ranking of districts across the 14 years was {N['kendall_W']:.2f}, and the BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f} to {N['phi'][2]:.2f}). After adjustment, {N['n_hot']} districts were residual hot spots ({N['hot_all_windows']} in all three windows), mainly in {sidos(N['hot_by_sido'], 4)}, comprising {_hot['county']} of {_nt['county']} counties, {_hot['city']} of {_nt['city']} cities and {_hot['ward']} of {_nt['ward']} urban wards; {N['n_cold']} were residual cold spots, mainly in {sidos(N['cold_by_sido'], 3)} (Figure 1A; {sup('persistence')}; district types in {sup('types')}). Emerging hot spot analysis found {N['ehsa']['Persistent hot']} persistent hot and {N['ehsa']['Persistent cold']} persistent cold districts. Residual hot spots were correlated with unadjusted smoothed SMRs (Spearman's rho {N['rr_eb']:.2f}); smoothed SMRs were correlated with the hepatitis C notification rate (rho {N['eb_hcv']:.2f}), the share of basic livelihood recipients (rho {N['eb_aid']:.2f}) and the share aged 80 years or older (rho {N['eb_p80']:.2f})."),
("District characteristics",
 f"Adding the {NHYP} characteristics changed WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}. Deaths were higher in districts with higher hepatitis C notification rates ({ci(HCV)}), more basic livelihood recipients ({ci(BLS)}), more current smokers ({ci(SMK)}), a higher screening share with suspected diabetes ({ci(DMS)}) and more adults doing moderate-or-vigorous physical activity ({ci(MPA)}), and lower in districts with more public sports facilities ({ci(FAC)}) (Table 2, Figure 2). Entertainment and singing bars ({ci(BAR)}), high-risk drinking ({ci(ALC)}), abdominal obesity ({ci(ABD)}), walking ({ci(WALK)}) and internal medicine specialists ({ci(IMS)}) were not credibly associated. Both negative-control exposures were credibly associated (fires, {_NC('fires_per_10000')}; breakfast, {_NC('breakfast_eating_rate')})."),
("Robustness",
 f"The six credible characteristics and bars were subset-stable ({100*N['mv'][FAC]['cred_frac']:.0f}% of subsets for sports facilities, {100*N['mv'][BAR]['cred_frac']:.0f}% for bars and 100% for the others). Hepatitis C notifications, smoking, basic livelihood recipients and public sports facilities remained credible in all four space-time interaction models, including type II, which had the lowest WAIC of the four ({abs(dW(BEST)):,.0f} lower than the principal model) ({tci(S43(BEST, HCV))} for hepatitis C; {tci(S43(BEST, SMK))} for smoking; {tci(S43(BEST, BLS))} for basic livelihood recipients; {tci(S43(BEST, FAC))} for sports facilities). Suspected diabetes was not credible in the type III and IV models ({tci(S43('KH_typeIV', DMS))} in type IV), moderate-or-vigorous physical activity not in type IV ({tci(S43('KH_typeIV', MPA))}), and bars were credible only in type II. Across {NALT} alternative specifications, hepatitis C, smoking and basic livelihood recipients were credible in all {NALT}, suspected diabetes and moderate-or-vigorous physical activity in {RET[DMS][0]} each, sports facilities in {RET[FAC][0]} and bars in {RET[BAR][0]}; sports facilities were not credible with 1- or 2-year lags ({sup('specs')}). Leaving out each province or year kept hepatitis C, smoking and basic livelihood recipients credible in all {N['leaveout'][('province', HCV)][0]} and {N['leaveout'][('year', HCV)][0]} refits, and suspected diabetes, moderate-or-vigorous physical activity and sports facilities in {min(N['leaveout'][(g, v)][1] for g in ('province', 'year') for v in (DMS, MPA, FAC))} to {max(N['leaveout'][(g, v)][1] for g in ('province', 'year') for v in (DMS, MPA, FAC))}. Hepatitis C, smoking, basic livelihood recipients, suspected diabetes and moderate-or-vigorous physical activity remained credible in all 20 refits with perturbed filled values and sports facilities in {N['rubin'][FAC]['n_cred']}; with district-type fixed effects, sports facilities were no longer credible ({tci(S45('E_district_type', FAC))}). Adding monthly drinking, suspected liver disease or the out-of-district outpatient share, or replacing abdominal obesity by self-reported obesity, left hepatitis C, smoking, basic livelihood recipients and moderate-or-vigorous physical activity credible; monthly drinking itself was not associated ({tci(S45('D_monthly_drinking', 'monthly_drinking_rate'))}) ({sup('prespec')}). With sex- and age-standardized expected deaths, the same six characteristics were credible ({tci(SC('ssx', HCV))} for hepatitis C) and bars were not."),
 (None,
 f"By calendar window, hepatitis C notifications and basic livelihood recipients were credible in 2011-2015, 2016-2019 and 2020-2024 ({tci(wt(HCV, WN[0]))}, {tci(wt(HCV, WN[1]))} and {tci(wt(HCV, WN[2]))} for hepatitis C), smoking in 2011-2015 and 2020-2024, suspected diabetes only in 2011-2015, and sports facilities, moderate-or-vigorous physical activity and bars in none. Smoking ({tci(BW(SMK, 'between'))}), suspected diabetes ({tci(BW(DMS, 'between'))}) and the time-invariant hepatitis C rate ({tci(BW(HCV, 'between'))}) were credible only between districts, basic livelihood recipients both between ({tci(BW(BLS, 'between'))}) and within districts ({tci(BW(BLS, 'within'))}), whereas sports facilities ({tci(BW(FAC, 'within'))}) and moderate-or-vigorous physical activity ({tci(BW(MPA, 'within'))}) were credible only within districts. Region-specific slopes lowered WAIC for smoking, basic livelihood recipients and hepatitis C, and the hepatitis C association was not credible in Honam or Gangwon-Jeju ({sup('regions')}). For the comparison outcomes, hepatitis C notifications and smoking were not credible for chronic lower respiratory disease or Alzheimer deaths; suspected diabetes was credible for both, basic livelihood recipients for chronic lower respiratory disease, and moderate-or-vigorous physical activity and sports facilities (in the opposite direction) for Alzheimer deaths. E-values for the point estimates of the six credible characteristics ranged from {min(N['evalue'][v]['E_point'] for v in CRED6):.2f} to {max(N['evalue'][v]['E_point'] for v in CRED6):.2f} ({N['evalue'][HCV]['E_point']:.2f} for hepatitis C)."),
 (None,
 f"In post hoc analyses, the share of farm-household residents was associated with liver deaths ({tci(S44('R3_measured_added', 'farm_share_z'))}) and its addition reduced the RR for moderate-or-vigorous physical activity to {S44('R3_measured_added', MPA)[0]:.3f} (95% CrI {S44('R3_measured_added', MPA)[1]:.3f} to {S44('R3_measured_added', MPA)[2]:.3f}); the association persisted alone with the forced controls ({tci(S44('R4_single_moderate_pa_rate', MPA))}) and without the other physical activity indicators ({tci(S44('R5_drop_pa', MPA))}) ({sup('reverse')}). Residual Moran's I was {N['moran_resid']:.3f} (P = {N['moran_resid_p']:.3f}). Posterior predictive 95% intervals covered {100*N['ppc']['coverage95']:.1f}% of district-years, the probability integral transform departed from uniformity (Kolmogorov-Smirnov P < 0.001), and with 2024 deaths withheld 95% predictive intervals covered {100*N['oos']['coverage95']:.1f}% of districts. In the space-time models, abdominal obesity became credible in the type III and IV models ({tci(S43('KH_typeIV', ABD))} in type IV)."),
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단) — 수급률 33칸 정정 재실행(11/11) 기준
H = [v for v in M if M[v]["role"] == "hypothesis"]; CRED6 = [HCV, BLS, SMK, DMS, MPA, FAC]
assert N["n_cred_hyp"] == 6 and {v for v in H if M[v]["cred"]} == set(CRED6) and set(ROB) == set(CRED6) | {BAR} and N["waic_main"] > N["waic_forced"]
assert M[FAC]["IRR"] < 1 and all(M[v]["IRR"] > 1 for v in CRED6 if v != FAC) and not M[BAR]["cred"] and not M[IMS]["cred"]
assert all(N["negctl"][v]["cred"] for v in ("fires_per_10000", "breakfast_eating_rate"))
assert all(N["mv"][v]["robust"] for v in ROB) and all(N["mv"][v]["cred_frac"] == 1 for v in CRED6 if v != FAC) and 0.75 <= N["mv"][BAR]["cred_frac"] < 1 and 0.75 <= N["mv"][FAC]["cred_frac"] < 1 and not N["mv"][IMS]["robust"]
assert all(S43(a, v)[3] for a in KH for v in (HCV, SMK, BLS, FAC)) and not S43("KH_typeIII", DMS)[3] and not S43("KH_typeIV", DMS)[3] and S43("KH_typeI", DMS)[3] and S43("KH_typeII", DMS)[3]
assert not S43("KH_typeIV", MPA)[3] and all(S43(a, MPA)[3] for a in ("KH_typeI", "KH_typeII", "KH_typeIII")) and [a for a in KH if S43(a, BAR)[3]] == ["KH_typeII"]
assert RET[HCV] == RET[SMK] == RET[BLS] == (14, 14) and RET[DMS][0] == RET[MPA][0] == 12 and RET[FAC][0] == 10 and RET[BAR][0] == 2 and NALT == 14
assert not any(S41(x, FAC)[3] for x in ("E1_lag1", "E2_lag2", "H4_odd_years", "H4_even_years"))
assert all(N["rubin"][v]["n_cred"] == 20 for v in (HCV, SMK, BLS, DMS, MPA)) and N["rubin"][FAC]["n_cred"] < 20 and not S45("E_district_type", FAC)[3]
assert all(wt(v, w)[3] for v in (HCV, BLS) for w in WN) and wt(SMK, WN[0])[3] and wt(SMK, WN[2])[3] and not wt(SMK, WN[1])[3] and wt(DMS, WN[0])[3] and not any(wt(DMS, w)[3] for w in WN[1:])
assert not any(wt(v, w)[3] for v in (FAC, MPA, BAR) for w in WN)
assert BW(SMK, "between")[3] and not BW(SMK, "within")[3] and BW(BLS, "between")[3] and BW(BLS, "within")[3] and BW(DMS, "between")[3] and not BW(DMS, "within")[3] and BW(HCV, "between")[3]
assert BW(FAC, "within")[3] and not BW(FAC, "between")[3] and BW(MPA, "within")[3] and not BW(MPA, "between")[3]
assert not any(NCO(o, v)[3] for o in ("CLRD", "ALZ") for v in (HCV, SMK)) and NCO("CLRD", DMS)[3] and NCO("ALZ", DMS)[3] and NCO("CLRD", BLS)[3] and not NCO("ALZ", BLS)[3]
assert NCO("ALZ", FAC)[3] and NCO("ALZ", FAC)[0] > 1 and not NCO("CLRD", FAC)[3] and NCO("ALZ", MPA)[3] and not NCO("CLRD", MPA)[3]
assert S41('E1_lag1', MPA)[3] and not S41('E2_lag2', MPA)[3] and not S45('D_monthly_drinking', 'monthly_drinking_rate')[3] and all(S45(a, v)[3] for a in ('A_liver_suspect','B_outside_care','C_obesity_selfreport','D_monthly_drinking') for v in (HCV, SMK, BLS, MPA))
assert not S44("R3_measured_added", MPA)[3] and S44("R3_measured_added", "farm_share_z")[3] and S44("R4_single_moderate_pa_rate", MPA)[3] and S44("R5_drop_pa", MPA)[3]
assert {v for v in N['sens_main']['ssx'] if N['sens_main']['ssx'][v][3] and v in H} == set(CRED6)
assert N["pit"][1] < 0.001 and ASR[2019] == min(ASR.values()) and S43("KH_typeIII", ABD)[3] and S43("KH_typeIV", ABD)[3]
assert all(N["s50_region"][(HCV, r)][3] for r in ("Capital", "Yeongnam", "Chungcheong")) and not any(N["s50_region"][(HCV, r)][3] for r in ("Honam", "Gangwon_Jeju"))
assert all(N["s50_region"][(SMK, r)][3] for r in ("Yeongnam", "Honam", "Chungcheong")) and not any(N["s50_region"][(SMK, r)][3] for r in ("Capital", "Gangwon_Jeju"))
assert N["s50_region_dwaic"][SMK] < N["s50_region_dwaic"][BLS] < N["s50_region_dwaic"][HCV] < 0
assert all(N["leaveout"][(g, v)][1] == str(N["leaveout"][(g, v)][0]) for g in ("province", "year") for v in (HCV, SMK, BLS))

if __name__ == "__main__":
    import re
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")
    print("words M", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in METHODS), "R", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in RESULTS))
